/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const path = require('path');
const ts = require('/rules/node_modules/arkanalyzer/node_modules/ohos-typescript');
const files = require('child_process').execFileSync('rg',['--files','entry/src/main/ets'],{encoding:'utf8'}).trim().split('\\n');
let errors = 0;
for (const file of files) {
  const text = fs.readFileSync(file,'utf8');
  const sf = ts.createSourceFile(file,text,ts.ScriptTarget.Latest,true,ts.ScriptKind.TS);
  const diagnostics = sf.parseDiagnostics || [];
  if (diagnostics.length) {
    errors += diagnostics.length;
    for (const d of diagnostics.slice(0,5)) console.log("'`${file}:${sf.getLineAndCharacterOfPosition(d.start||0).line+1}: ${ts.flattenDiagnosticMessageText(d.messageText,'"' ')}"'`);
  }
}
console.log(`parse diagnostics: ${errors}`);
process.exitCode = errors ? 1 : 0;
NODE'

