/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const p = 'entry/src/main/ets/MainAbility/pages/SymbolGlyph/SymbolGlyphApi.ets';
const s = fs.readFileSync(p, 'utf8');
const body = s.replace(/\\/\\*[\\s\\S]*?\\*\\/|\\/\\/.*|\"(?:\\\\.|["'^"'"\\\\])*\"|'(?:\\\\.|["'^'"'\\\\])*'/g, '');
const pairs = [['(', ')'], ['{', '}'], ['[', ']']];
const result = {};
for (const [open, close] of pairs) {
  let depth = 0;
  for (const c of body) { if (c === open) depth++; else if (c === close) depth--; if (depth < 0) throw new Error("'`unbalanced ${open}${close}`); }
  result[`${open}${close}`] = depth;
}
console.log(JSON.stringify({balanced: Object.values(result).every(v => v === 0), result}));
NODE'

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_02/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion.json', 'utf8'));
const expected = plan.rules.map(r => r.rule);
const required = ['selected_rules', 'entity_repairs', 'blocked', 'unresolved_external'];
for (const key of required) if ("'!(key in report)) throw new Error(`missing ${key}`);
if (JSON.stringify(report.selected_rules) !== JSON.stringify(expected)) throw new Error('"'selected_rules mismatch');
if (report.blocked.length "'!== 0 || report.unresolved_external.length !== 0) throw new Error('"'blocked/external findings present');
if (report.entity_repairs.length "'!== 1) throw new Error('"'unexpected repair count');
const repair = report.entity_repairs[0];
for (const key of ['rule','relative_path','locations','entities','evidence','transformation','status']) if ("'!(key in repair)) throw new Error(`missing repair key ${key}`);
if (repair.status !== '"'repaired' || repair.locations.length < 1 || repair.entities.length < 1 || repair.evidence.length < 1 || "'!repair.transformation) throw new Error('"'repair constraints failed');
if ('repository_evidence' in repair) throw new Error('wrong evidence key present');
console.log('completion.json validation: PASS');
NODE"

